const events = $input.first().json.body;

if (!Array.isArray(events)) {
  return [{ json: { skip: true, reason: "Unexpected payload shape" } }];
}

const PERSONA_MAP = { 'persona_2': 'QC Manager', 'persona_3': 'R&D' };

return events
  .filter(e => e.propertyName === 'hs_persona')
  .map(e => {
    const label = PERSONA_MAP[e.propertyValue];
    return {
      json: {
        objectId: e.objectId,
        rawPersonaValue: e.propertyValue,
        personaLabel: label || null,
        recognized: !!label,
        hubspotEventId: e.eventId,
        attemptNumber: e.attemptNumber
      }
    };
  });

