const event = $('Code: Filter Persona Events').first().json;
const contact = $('HTTP Request: Get Contact Email').first().json;
const rows = $input.all();

const PERSONA_MAP = { 'persona_2': 'QC Manager', 'persona_3': 'R&D' };

const currentPersonaRaw = contact.properties.hs_persona;
const currentPersonaLabel = PERSONA_MAP[currentPersonaRaw] || null;

let previousPersona = null;
if (rows.length) {
    previousPersona = rows[0].json["Last Synced Persona"] || null;
}

const email = contact.properties.email;
const isSuppressed = contact.properties.hs_email_optout === true || contact.properties.hs_email_optout === 'true';
const emailLooksValid = typeof email === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

return [{
    json: {
        email,
        emailLooksValid,
        objectId: event.objectId,
        hubspotContactId: event.objectId,
        hubspotEventId: event.hubspotEventId,
        attemptNumber: event.attemptNumber,
        previousPersona,
        newPersona: currentPersonaLabel,
        webhookClaimedPersona: event.personaLabel,
        isSuppressed,
        needsSync: previousPersona !== currentPersonaLabel && !!currentPersonaLabel && emailLooksValid
    }
}];

