const crypto = require('crypto');

const headers = $json.headers || {};
const rawBody = $json.body; // Raw Body is enabled on the webhook node, so this is the exact string HubSpot signed
const timestampHeader = headers['x-hubspot-request-timestamp'];
const signatureV3 = headers['x-hubspot-signature-v3'];

// CONFIG: set HUBSPOT_CLIENT_SECRET as an n8n environment variable (Settings > Environment Variables)
// using the Client Secret of the HubSpot Private App / Public App this webhook subscription belongs to.
const clientSecret = $env.HUBSPOT_CLIENT_SECRET || '';

let isValid = false;
let reason = '';

if (!clientSecret) {
  reason = 'HUBSPOT_CLIENT_SECRET environment variable is not configured';
} else if (!signatureV3 || !timestampHeader) {
  reason = 'Missing HubSpot signature or timestamp header';
} else {
  // Reject requests older than 5 minutes to prevent replay attacks
  const ageMs = Date.now() - parseInt(timestampHeader, 10);
  if (isNaN(ageMs) || ageMs > 5 * 60 * 1000 || ageMs < -60 * 1000) {
    reason = 'Request timestamp outside the allowed window';
  } else {
    const method = 'POST';
    // NOTE: this must exactly match the URL HubSpot calls (protocol + host + path).
    // Double check this against your n8n instance's public webhook URL before relying on it.
    let requestUri = $json.webhookUrl || '';
    const sourceString = clientSecret + method + requestUri + rawBody + timestampHeader;
    const expectedHash = crypto.createHmac('sha256', clientSecret).update(sourceString).digest('base64');
    isValid = expectedHash === signatureV3;
    if (!isValid) reason = 'Signature mismatch';
  }
}

let parsedBody;
try {
  parsedBody = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
} catch (e) {
  parsedBody = null;
  if (isValid) { isValid = false; reason = 'Body was not valid JSON'; }
}

return [{
  json: {
    ...$json,
    body: parsedBody,
    signatureValid: isValid,
    signatureFailureReason: reason
  }
}];

