const error = $json.error || {};
const code = error.httpCode || 500;
const isTransient = code == 429 || code >= 500;
const retryCount = ($json.retryCount || 0) + 1;

if (!isTransient) {
    return { json: { ...$json, retryCount, failReason: 'Persistent error (HTTP ' + code + ')', action: 'fail' } };
}
if (retryCount > 3) {
    return { json: { ...$json, retryCount, failReason: 'Max retries exceeded', action: 'fail' } };
}
return { json: { ...$json, retryCount, action: 'retry' } };
